import { expect, test, uniqueName } from "../../fixtures";

test("creating a vendor returns 201 as a draft and records an audit event", { tag: "@VEN-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const name = uniqueName("Acme Freight");

  // Act
  const res = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  expect(res.status(), await res.text()).toBe(201);
  const vendor = await res.json();
  expect(vendor.name).toBe(name);
  expect(vendor.category).toBe("logistics");
  expect(vendor.contact_email).toBe("ops@acmefreight.example");
  expect(vendor.status, await res.text()).toBe("draft");

  await expect
    .poll(
      async () => {
        const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(audit.status(), await audit.text()).toBe(200);
        const body = (await audit.json()) as { items: { action: string }[] };
        return body.items.map((event) => event.action);
      },
      { message: "vendor.created should be recorded in the audit trail" },
    )
    .toContain("vendor.created");
});
